(() => {
  // site-src/format.ts
  function formatWeight(kg) {
    if (kg < 1) {
      return Math.round(kg * 1e3) + " g";
    }
    return kg.toFixed(1) + " kg";
  }

  // site-src/status.ts
  function statusLabel(status) {
    switch (status) {
      case "in_transit":
        return "In transit";
      case "delivered":
        return "Delivered";
      default:
        return "Returned to sender";
    }
  }

  // site-src/main.ts
  var parcels = {
    "PX-1042": { weight: 0.4, status: "in_transit" },
    "PX-2077": { weight: 12.5, status: "delivered" }
  };
  function track(code) {
    const parcel = parcels[code];
    if (!parcel) {
      return "No parcel " + code;
    }
    return statusLabel(parcel.status) + ", " + formatWeight(parcel.weight);
  }
  document.getElementById("track").addEventListener("click", () => {
    const code = document.getElementById("code").value;
    document.getElementById("result").textContent = track(code);
  });
})();
